import React from 'react';

const Hero = () => {
  const s = {
    section: {
      paddingTop: 66,
      background: '#F4F4F4',
      position: 'relative',
      overflow: 'hidden',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      fontFamily: 'Poppins, sans-serif',
    },
    bgWrap: {
      position: 'absolute',
      inset: 0,
      zIndex: 0,
      opacity: 0.4,
      objectFit: 'cover',
      width: '100%',
      height: '100%',
    },
    wrapper: {
      maxWidth: 1200, margin: '0 auto', padding: '80px 32px 0',
      position: 'relative', zIndex: 1, flex: 1,
      display: 'flex', flexDirection: 'column', 
    },
    h1: {
      fontFamily: 'Poppins, sans-serif',
      fontSize: 34, fontWeight: 800,
      lineHeight: 1.12, color: '#535050',
      maxWidth: 700, marginBottom: 32,
      letterSpacing: '- 4px',
      textAlign: 'right',
    },
    h1Orange: { color: '#FF5A00' },
    sub: {
      fontSize: 14.5, color: '#777',
      maxWidth: 500, lineHeight: 1.8,
      fontFamily: 'Poppins, sans-serif', fontWeight: 400,
      marginBottom: 40,
    },
    btn: {
      display: 'inline-flex', alignItems: 'center',
      background: 'transparent',
      color: '#FF5A00',
      // padding: '13px 18px',
      borderRadius: 10,
      fontSize: 14, fontWeight: 600,
      border: '1.8px solid #FF5A00',
      cursor: 'pointer',
      fontFamily: 'Poppins, sans-serif',
      // transition: 'all .2s',
      marginBottom: 60,
    },
    partnersWrap: {
      display: 'flex', alignItems: 'center', gap: 8,
      flexWrap: 'wrap', marginBottom: 60,
    },
    partnerLabel: { fontSize: 14, color: '#999', fontFamily: 'Poppins, sans-serif', fontWeight: 400 },
    chip: {
      background: '#EBEBEB', color: '#555',
      padding: '5px 14px', borderRadius: 20,
      fontSize: 13, fontWeight: 600,
      fontFamily: 'Poppins, sans-serif',
    },
  };

  const partners = ['BBDA', 'Orange Burkina', 'BSL', 'MTDPCE', 'SITHO', 'SIAO'];

  return (
    <section style={s.section}>
      <img src="/Rectangle 9.png" alt="background" style={s.bgWrap} />

      <div style={s.wrapper}>
        <h1 style={s.h1}>
          <span style={s.h1Orange}>Une plateforme</span>qui vous connecte à <br />
          tout ce qui fait vivre l'événementiel.
        </h1><br /><br />

        <p style={s.sub}>
          Contrary to popular belief, Lorem Ipsum is not simply random text. It has roots in a
          piece of classical Latin literature from{' '}
          45 BC, making it over 2000 years old. Richard McClintock, a Latin professor at
          Hampden-Sydney College in Virginia, .
        </p>

        <button style={s.btn}>Voir les évènements</button>

        <div style={s.partnersWrap}>
          <span style={s.partnerLabel}>Reconnu par :</span>
          {partners.map(p => (
            <span key={p} style={s.chip}>{p}</span>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Hero;
